	public int getAnalogSignalStrength(int redstoneMode)
	{
		switch (redstoneMode)
		{
		case 0:
			return getCurrentBlood() * 15 / getCapacity();

		case 1:
			ItemStack contained = tileAltar.getItem(0);

			if (contained.isEmpty() || !(contained.getItem() instanceof IBloodOrb) || !(contained.getItem() instanceof IBindable))
				return 0;

			BloodOrb orb = ((IBloodOrb) contained.getItem()).getOrb(contained);
			Binding binding = ((IBindable) contained.getItem()).getBinding(contained);

			if (binding == null || orb == null)
				return 0;

            SoulNetwork network = NetworkHelper.getSoulNetwork(binding);
            if (network == null)
                return 0;

            // see AbstractContainerMenu#getRedstoneSignalFromContainer
			//compare the soul network's fill level to the orb's capacity and output a redstone signal.
			//capped at 15 in case the orb is smaller than the network.

            return Math.min(15,
					Mth.floor((float) network.getCurrentEssence() / (float) orb.getCapacity() * 14.0F) + (network.getCurrentEssence() > 0 ? 1 : 0));

		default:
			return 0;
		}
	}

