			if (inventory.get(index).getCount() <= count)
			{
				ItemStack itemStack = inventory.get(index);
				inventory.set(index, ItemStack.EMPTY);
				setChanged();
				return itemStack;
			}

			ItemStack itemStack = inventory.get(index).split(count);
			if (inventory.get(index).isEmpty())
				inventory.set(index, ItemStack.EMPTY);

			setChanged();
			return itemStack;
		}

		return null;
	}

