package wayoftime.bloodmagic.core.data;

import java.util.UUID;

import javax.annotation.Nullable;

import net.minecraft.world.item.ItemStack;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.Tag;
import net.minecraft.nbt.NbtUtils;
import net.minecraftforge.common.util.INBTSerializable;

public class Binding implements INBTSerializable<CompoundTag>
{
	private UUID uuid;
	private String name;

	public Binding(UUID uuid, String name)
	{
		this.uuid = uuid;
		this.name = name;
	}

	private Binding()
	{
		// No-op
	}

	@Override
	public CompoundTag serializeNBT()
	{
		CompoundTag tag = new CompoundTag();
//		tag.put("id", NBTUtil.writeUniqueId(uuid));
		tag.put("id", NbtUtils.createUUID(uuid));
		tag.putString("name", name);
		return tag;
	}

	@Override
	public void deserializeNBT(CompoundTag nbt)
	{
		this.uuid = NbtUtils.loadUUID(nbt.get("id"));
		this.name = nbt.getString("name");
	}

	public UUID getOwnerId()
	{
		return uuid;
	}

	public Binding setOwnerId(UUID uuid)
	{
		this.uuid = uuid;
		return this;
	}

	public String getOwnerName()
	{
		return name;
	}

	public Binding setOwnerName(String name)
	{
		this.name = name;
		return this;
	}

	@Nullable
	public static Binding fromStack(ItemStack stack)
	{
		if (!stack.hasTag()) // Definitely hasn't been bound yet.
			return null;

		Tag bindingTag = stack.getTag().get("binding");
		if (bindingTag == null || bindingTag.getId() != 10) // Make sure it's both a tag compound and that it has actual
															// data.
			return null;

		Binding binding = new Binding();
		binding.deserializeNBT((CompoundTag) bindingTag);
		return binding;
	}

	@Override
	public String toString()
	{
		return "Binding{" + "uuid=" + uuid + ", name='" + name + '\'' + '}';
	}
}

package wayoftime.bloodmagic.core.data;

import java.util.List;
import java.util.Queue;
import java.util.UUID;

import javax.annotation.Nullable;

import com.google.common.collect.EvictingQueue;
import com.google.common.collect.ImmutableList;

import net.minecraft.world.entity.player.Player;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.world.effect.MobEffectInstance;
import net.minecraft.world.effect.MobEffects;
import net.minecraftforge.common.MinecraftForge;
import net.minecraftforge.common.util.INBTSerializable;
import wayoftime.bloodmagic.common.registries.BloodMagicDamageTypes;
import wayoftime.bloodmagic.event.SoulNetworkEvent;
import wayoftime.bloodmagic.util.BMLog;
import wayoftime.bloodmagic.util.BooleanResult;
import wayoftime.bloodmagic.util.helper.PlayerHelper;

public class SoulNetwork implements INBTSerializable<CompoundTag>
{

	private final Queue<SoulTicket> ticketHistory;
	private BMWorldSavedData parent;
	private Player cachedPlayer;
	private UUID playerId;
	private int currentEssence;
	private int orbTier;

	private SoulNetwork()
	{
		// No-op - For creation via NBT only
		ticketHistory = EvictingQueue.create(16);
	}

	public void clear()
	{
		ticketHistory.clear();
	}

	public int add(SoulTicket ticket, int maximum)
	{
		SoulNetworkEvent.Fill event = new SoulNetworkEvent.Fill(this, ticket, maximum);
		if (MinecraftForge.EVENT_BUS.post(event))
			return 0;

		int currEss = getCurrentEssence();

		if (currEss >= event.getMaximum())
			return 0;

		int newEss = Math.min(event.getMaximum(), currEss + event.getTicket().getAmount());
		setCurrentEssence(newEss);

		if (ticketHistory.contains(ticket))
			ticketHistory.remove(ticket); // "Pops" the existing ticket to the top of the queue

		ticketHistory.add(ticket);

		return newEss - currEss;
	}

	/**
	 * @deprecated For future proofing, use {@link #add(SoulTicket, int)} instead.
	 */
	@Deprecated
	public int add(int toAdd, int maximum)
	{
		return add(new SoulTicket(toAdd), maximum);
	}

	/**
	 * @deprecated Use {@link #add(SoulTicket, int)} instead.
	 */
	@Deprecated
	public int addLifeEssence(int toAdd, int maximum)
	{
		return add(toAdd, maximum);
	}

	public int syphon(SoulTicket ticket)
	{
		return syphon(ticket, false);
	}

	public int syphon(SoulTicket ticket, boolean skipEvent)
	{
		SoulNetworkEvent.Syphon event = new SoulNetworkEvent.Syphon(this, ticket);
		if (!skipEvent && MinecraftForge.EVENT_BUS.post(event))
			return 0;

		int syphon = event.getTicket().getAmount();
		if (getCurrentEssence() >= syphon)
		{
			setCurrentEssence(getCurrentEssence() - syphon);
			if (ticketHistory.contains(ticket))
				ticketHistory.remove(ticket);

			ticketHistory.add(ticket);
			return syphon;
		}

		return 0;
	}

	/**
	 * @deprecated For future proofing, use {@link #syphon(SoulTicket)} instead.
	 */
	@Deprecated
	public int syphon(int amount)
	{
		return syphon(new SoulTicket(amount));
	}

	public BooleanResult<Integer> syphonAndDamage(Player user, SoulTicket ticket)
	{
		if (user.getCommandSenderWorld().isClientSide)
			return BooleanResult.newResult(false, 0);

		SoulNetworkEvent.Syphon.User event = new SoulNetworkEvent.Syphon.User(this, ticket, user);

		if (MinecraftForge.EVENT_BUS.post(event))
			return BooleanResult.newResult(false, 0);

		int drainAmount = syphon(event.getTicket(), true);

		if (drainAmount <= 0 || event.shouldDamage())
			hurtPlayer(user, event.getTicket().getAmount());

		if (ticketHistory.contains(ticket))
			ticketHistory.remove(ticket);

		ticketHistory.add(ticket);

		return BooleanResult.newResult(true, event.getTicket().getAmount());
	}

	/**
	 * @deprecated Use {@link #syphonAndDamage(Player, SoulTicket)} instead.
	 */
	@Deprecated
	public boolean syphonAndDamage(Player user, int amount)
	{
		return syphonAndDamage(user, new SoulTicket(amount)).isSuccess();
	}

	public void causeNausea()
	{
		if (getPlayer() != null)
			getPlayer().addEffect(new MobEffectInstance(MobEffects.CONFUSION, 99));
	}

	/**
	 * @deprecated - Please use {@link #causeNausea()}
	 */
	@Deprecated
	public void causeNauseaToPlayer()
	{
		causeNausea();
	}

	public void hurtPlayer(Player user, float syphon)
	{
		if (user != null)
		{
			if (syphon < 100 && syphon > 0)
			{
				if (!user.isCreative())
				{
					user.invulnerableTime = 0;
					user.hurt(user.damageSources().source(BloodMagicDamageTypes.SACRIFICE), 1.0F);
				}

			} else if (syphon >= 100)
			{
				if (!user.isCreative())
				{
					for (int i = 0; i < ((syphon + 99) / 100); i++)
					{
						user.invulnerableTime = 0;
						user.hurt(user.damageSources().source(BloodMagicDamageTypes.SACRIFICE), 1.0F);
					}
				}
			}
		}
	}

	private void markDirty()
	{
		if (getParent() != null)
			getParent().setDirty();
		else
			BMLog.DEFAULT.error("A SoulNetwork was created, but a parent was not set to allow saving.");
	}

	@Nullable
	public Player getPlayer()
	{
		if (cachedPlayer == null)
			cachedPlayer = PlayerHelper.getPlayerFromUUID(playerId);

		return cachedPlayer;
	}

	public BMWorldSavedData getParent()
	{
		return parent;
	}

	public SoulNetwork setParent(BMWorldSavedData parent)
	{
		this.parent = parent;
		markDirty();
		return this;
	}

	public Player getCachedPlayer()
	{
		return cachedPlayer;
	}

	public UUID getPlayerId()
	{
		return playerId;
	}

	public int getCurrentEssence()
	{
		return currentEssence;
	}

	public SoulNetwork setCurrentEssence(int currentEssence)
	{
		this.currentEssence = currentEssence;
		markDirty();
		return this;
	}

	public int getOrbTier()
	{
		return orbTier;
	}

	public SoulNetwork setOrbTier(int orbTier)
	{
		this.orbTier = orbTier;
		markDirty();
		return this;
	}

	public List<SoulTicket> getTicketHistory()
	{
		return ImmutableList.copyOf(ticketHistory);
	}

	// INBTSerializable

	@Override
	public CompoundTag serializeNBT()
	{
		CompoundTag tagCompound = new CompoundTag();
		tagCompound.putString("playerId", getPlayerId().toString());
		tagCompound.putInt("currentEssence", getCurrentEssence());
		tagCompound.putInt("orbTier", getOrbTier());
		return tagCompound;
	}

	@Override
	public void deserializeNBT(CompoundTag nbt)
	{
		this.playerId = UUID.fromString(nbt.getString("playerId"));
		this.currentEssence = nbt.getInt("currentEssence");
		this.orbTier = nbt.getInt("orbTier");
	}

	public static SoulNetwork fromNBT(CompoundTag tagCompound)
	{
		SoulNetwork soulNetwork = new SoulNetwork();
		soulNetwork.deserializeNBT(tagCompound);
		return soulNetwork;
	}

	public static SoulNetwork newEmpty(UUID uuid)
	{
		SoulNetwork network = new SoulNetwork();
		network.playerId = uuid;
		return network;
	}
}

package wayoftime.bloodmagic.core.living;

import net.minecraft.ChatFormatting;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.chat.Component;
import net.minecraft.world.item.ItemStack;
import net.minecraftforge.api.distmarker.Dist;
import net.minecraftforge.api.distmarker.OnlyIn;
import wayoftime.bloodmagic.util.Constants;

import java.util.List;

public interface ILivingContainer
{
	default LivingStats getLivingStats(ItemStack stack)
	{
		if (!stack.hasTag() || !stack.getTag().contains("livingStats"))
			return null;

		return LivingStats.fromNBT(stack.getTag().getCompound("livingStats"));
	}

	default void updateLivingStats(ItemStack stack, LivingStats stats)
	{
		if (stats == null)
		{
			if (stack.hasTag())
				stack.getTag().remove("livingStats");
			return;
		}

		if (!stack.hasTag())
			stack.setTag(new CompoundTag());

		stack.getTag().put("livingStats", stats.serialize());
	}

	static void setDisplayIfZero(ItemStack stack, boolean doDisplay)
	{
		if (!stack.hasTag())
		{
			stack.setTag(new CompoundTag());
		}

		stack.getTag().putBoolean(Constants.NBT.UPGRADE_ZERO_DISPLAY, doDisplay);
	}

	static boolean displayIfLevelZero(ItemStack stack)
	{
		if (stack.hasTag())
		{
			return stack.getTag().getBoolean(Constants.NBT.UPGRADE_ZERO_DISPLAY);
		}

		return false;
	}

	@OnlyIn(Dist.CLIENT)
	static void appendLivingTooltip(ItemStack stack, LivingStats stats, List<Component> tooltip, boolean trainable)
	{
		if (stats != null)
		{
			if (trainable)
				tooltip.add(Component.translatable("tooltip.bloodmagic.livingarmour.upgrade.points", stats.getUsedPoints(), stats.getMaxPoints()).withStyle(ChatFormatting.GOLD));

			stats.getUpgrades().forEach((k, v) -> {
				if (k.getLevel(v.intValue()) <= 0 && !displayIfLevelZero(stack))
					return;

				boolean sneaking = Screen.hasShiftDown();
//				if (!InputUtil.isKeyPressed(MinecraftClient.getInstance().getWindow().getHandle(), 340) || k.getNextRequirement(v) == 0)
				if (!sneaking || k.getNextRequirement(v.intValue()) == 0)
				{
					int level = k.getLevel(v.intValue());
					if (level > 0)
						tooltip.add(Component.translatable("%s %s", Component.translatable(k.getTranslationKey()), Component.translatable("enchantment.level." + level)).withStyle(ChatFormatting.GRAY));
					else
						tooltip.add(Component.translatable(k.getTranslationKey()).withStyle(ChatFormatting.GRAY));
				} else
					tooltip.add(Component.translatable("%s %s", Component.translatable(k.getTranslationKey()), (": " + v.intValue() + "/" + k.getNextRequirement(v.intValue()))).withStyle(ChatFormatting.GRAY));
			});
		}
	}

    default boolean canLivingEvolve(){
        return false;
    }
}

package wayoftime.bloodmagic.core.living;

import java.util.Map;
import java.util.function.Supplier;

import com.google.common.collect.ImmutableMap;
import com.google.common.collect.Maps;

import net.minecraft.world.entity.player.Player;
import net.minecraft.world.entity.EquipmentSlot;
import net.minecraft.world.item.ItemStack;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.ListTag;
import net.minecraft.resources.ResourceLocation;
import wayoftime.bloodmagic.ConfigManager;
import wayoftime.bloodmagic.core.LivingArmorRegistrar;

public class LivingStats
{

	protected final Map<LivingUpgrade, Double> upgrades;
	protected Supplier<Integer> maxPoints;
    protected boolean evolved = false;

	public LivingStats(Map<LivingUpgrade, Double> upgrades)
	{
		this.upgrades = upgrades;
        this.maxPoints = ConfigManager.COMMON.defaultUpgradePoints;
	}

	public LivingStats()
	{
		this(Maps.newHashMap());
	}

	public Map<LivingUpgrade, Double> getUpgrades()
	{
		return ImmutableMap.copyOf(upgrades);
	}

	public LivingStats addExperience(ResourceLocation key, double experience)
	{
//		LivingUpgrade upgrade = LivingArmorRegistrar.UPGRADES.getOrDefault(key);
		LivingUpgrade upgrade = LivingArmorRegistrar.UPGRADE_MAP.getOrDefault(key, LivingUpgrade.DUMMY);
		double current = upgrades.getOrDefault(upgrade, 0d);

//		System.out.println("Resource key: " + key + ", Upgrade: " + upgrade);

		if (experience > 0 && upgrade.getNextRequirement((int) current) == 0)
			return this;

		upgrades.put(upgrade, current + experience);

		return this;
	}

	public LivingStats resetExperience(ResourceLocation key)
	{
		LivingUpgrade upgrade = LivingArmorRegistrar.UPGRADE_MAP.getOrDefault(key, LivingUpgrade.DUMMY);
//		double current = upgrades.getOrDefault(upgrade, 0d);

		if (!upgrades.containsKey(upgrade))
			return this;

		upgrades.put(upgrade, 0d);

		return this;
	}

	public int getLevel(ResourceLocation key)
	{
		LivingUpgrade upgrade = LivingArmorRegistrar.UPGRADE_MAP.getOrDefault(key, LivingUpgrade.DUMMY);
//		LivingUpgrade upgrade = LivingArmorRegistrar.UPGRADES.getOrDefault(key);
		return upgrade.getLevel(upgrades.getOrDefault(upgrade, 0d).intValue());
	}

	public int getUsedPoints()
	{
		int total = 0;
		for (Map.Entry<LivingUpgrade, Double> applied : upgrades.entrySet())
		{
			double experience = applied.getValue();
			int level = applied.getKey().getLevel((int) experience);
			int cost = applied.getKey().getLevelCost(level);
			total += cost;
		}

		return total;
	}

	public int getMaxPoints()
	{
		return maxPoints.get();
	}

	public LivingStats setMaxPoints(int maxPoints)
	{
		this.maxPoints = () -> maxPoints;
		return this;
	}

    public boolean isEvolved()
    {
        return evolved;
    }

    public LivingStats setEvolved()
    {
        this.evolved = true;
        this.setMaxPoints(ConfigManager.COMMON.evolvedUpgradePoints.get());
        return this;
    }

	public CompoundTag serialize()
	{
		CompoundTag compound = new CompoundTag();
		ListTag statList = new ListTag();
		upgrades.forEach((k, v) -> {
			CompoundTag upgrade = new CompoundTag();
			upgrade.putString("key", k.getKey().toString());
			upgrade.putDouble("exp", v);
			statList.add(upgrade);
		});
		compound.put("upgrades", statList);
		compound.putInt("maxPoints", maxPoints.get());
        compound.putBoolean("evolved", evolved);

		return compound;
	}

	public void deserialize(CompoundTag nbt)
	{
		ListTag statList = nbt.getList("upgrades", 10);
		statList.forEach(tag -> {
			if (!(tag instanceof CompoundTag))
				return;

			LivingUpgrade upgrade = LivingArmorRegistrar.UPGRADE_MAP.getOrDefault(new ResourceLocation(((CompoundTag) tag).getString("key")), LivingUpgrade.DUMMY);
			if (upgrade == LivingUpgrade.DUMMY)
				return;
			double experience = ((CompoundTag) tag).getDouble("exp");
			upgrades.put(upgrade, experience);
		});

		maxPoints = () -> nbt.getInt("maxPoints");
        evolved = nbt.getBoolean("evolved");
	}

	public static LivingStats fromNBT(CompoundTag statTag)
	{
		LivingStats stats = new LivingStats();
		stats.deserialize(statTag);
		return stats;
	}

	public static LivingStats fromPlayer(Player player)
	{
		return fromPlayer(player, false);
	}

	public static LivingStats fromPlayer(Player player, boolean createNew)
	{
		if (!LivingUtil.hasFullSet(player))
			return null;

		ItemStack chest = player.getItemBySlot(EquipmentSlot.CHEST);
		LivingStats stats = ((ILivingContainer) chest.getItem()).getLivingStats(chest);
		return stats == null && createNew ? new LivingStats() : stats;
	}

	public static void toPlayer(Player player, LivingStats stats)
	{
		if (!LivingUtil.hasFullSet(player))
			return;

		ItemStack chest = player.getItemBySlot(EquipmentSlot.CHEST);
		((ILivingContainer) chest.getItem()).updateLivingStats(chest, stats);
	}
}

